INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u4-C1','math',4,2,'u4',2,'다각형 — 선분으로만 둘러싸인 도형으로, 곡선이 한 군데라도 섞이거나 열려 있으면 다각형이 아니며, 삼각형·사각형도 다각형이다',ARRAY['4수03-11']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u4-C2','math',4,2,'u4',2,'변과 꼭짓점 세기 — 다각형의 변과 꼭짓점을 빠짐없이, 겹치지 않게 세고, 다각형의 변의 수와 꼭짓점의 수는 언제나 같다',ARRAY['4수03-11']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u4-C3','math',4,2,'u4',3,'다각형의 이름 — 다각형은 변의 수에 따라 오각형·육각형·칠각형·팔각형…으로 부르며, 같은 이름이라도 모양과 크기는 여러 가지이다',ARRAY['4수03-11']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u4-C4','math',4,2,'u4',4,'정다각형 — 변의 길이가 모두 같고 각의 크기가 모두 같은 다각형으로, 둘 가운데 하나만 같으면 정다각형이 아니며, 이름 앞에 「정」을 붙인다',ARRAY['4수03-11']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u4-C5','math',4,2,'u4',4,'정다각형의 변과 각 — 정다각형은 모든 변의 길이의 합 = 한 변 × 변의 수이고, 한 각의 크기를 알면 모든 각의 크기를 안다',ARRAY['4수03-11']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u4-C6','math',4,2,'u4',5,'대각선 — 다각형에서 서로 이웃하지 않는 두 꼭짓점을 이은 선분으로, 이웃한 꼭짓점을 이으면 변이고, 두 끝이 모두 꼭짓점이어야 한다',ARRAY['4수03-11']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u4-C7','math',4,2,'u4',5,'대각선의 수와 사각형의 대각선 — 한 꼭짓점에서 차례로 그어 빠짐없이 세고(삼각형 0·사각형 2·오각형 5·육각형 9), 사각형의 두 대각선의 길이·만나는 모양을 견준다',ARRAY['4수03-11']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u4-C8','math',4,2,'u4',6,'모양 만들기 — 모양 조각을 겹치지 않게, 길이가 같은 변끼리 맞대어 이어 붙이고, 어떤 조각을 몇 개 썼는지와 만든 도형의 이름을 말한다',ARRAY['4수03-12']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u4-C9','math',4,2,'u4',7,'모양 채우기 — 주어진 모양을 조각으로 겹치지 않고 빈틈없이 채우며, 같은 모양이라도 쓰는 조각에 따라 채우는 방법과 조각 수가 달라진다',ARRAY['4수03-12']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u4-C10','math',4,2,'u4',8,'조각을 모아 다각형 만들기 — 조각을 모아 만든 도형의 이름은 쓴 조각의 수가 아니라 바깥쪽 변의 수로 정하고, 조건에 맞는 다각형을 여러 가지로 만든다',ARRAY['4수03-12']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u4-X01','math',4,'u4',ARRAY['M4-2-u4-C1']::text[],'선분이 들어 있기만 하면 다각형이라고 생각한다 — 곡선이 한 군데 섞였거나 끝이 열려 있어도 다각형이라고 한다','선분으로만, 그리고 둘러싸였는지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u4-X02','math',4,'u4',ARRAY['M4-2-u4-C1','M4-2-u4-C3']::text[],'뾰족한 곳(각)이 많으면 다각형이라고 생각한다 — 변이 아니라 각에 눈을 둔다','각이 아니라 변을 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u4-X03','math',4,'u4',ARRAY['M4-2-u4-C1','M4-2-u4-C3']::text[],'삼각형·사각형은 변이 적어서 다각형이 아니라고 생각한다','삼각형·사각형도 다각형') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u4-X04','math',4,'u4',ARRAY['M4-2-u4-C2','M4-2-u4-C3','M4-2-u4-C10']::text[],'변을 셀 때 하나를 빠뜨리거나 두 번 세어 변의 수(이름)를 하나 어긋나게 말한다','한 곳에서 시작해 표시하며 세기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u4-X05','math',4,'u4',ARRAY['M4-2-u4-C3']::text[],'같은 이름의 다각형은 모양·크기가 같아야 한다고 생각한다 — 오목하거나 길쭉하면 그 이름이 아니라고 한다','이름은 변의 수로만') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u4-X06','math',4,'u4',ARRAY['M4-2-u4-C2','M4-2-u4-C3']::text[],'다각형의 꼭짓점의 수가 변의 수와 다르다고 생각한다(하나 더 많거나 적다고 한다)','변의 수 = 꼭짓점의 수') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u4-X07','math',4,'u4',ARRAY['M4-2-u4-C4']::text[],'변의 길이만 모두 같으면 정다각형이라고 생각한다 — 각의 크기를 확인하지 않는다','각의 크기도 모두 같은지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u4-X08','math',4,'u4',ARRAY['M4-2-u4-C4']::text[],'각의 크기만 모두 같으면 정다각형이라고 생각한다 — 변의 길이를 확인하지 않는다','변의 길이도 모두 같은지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u4-X10','math',4,'u4',ARRAY['M4-2-u4-C4','M4-2-u4-C5']::text[],'정다각형은 크기가 정해져 있거나 반듯하게 놓여야 한다고 생각한다 — 크기가 다르거나 돌려 놓으면 정다각형이 아니라고 한다','크기·놓인 방향과 상관없이') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u4-X11','math',4,'u4',ARRAY['M4-2-u4-C6','M4-2-u4-C7']::text[],'이웃한 두 꼭짓점을 이은 선분(변)도 대각선이라고 생각한다','이웃하지 않는 꼭짓점끼리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u4-X12','math',4,'u4',ARRAY['M4-2-u4-C6']::text[],'꼭짓점과 변의 가운데를 이은 선분이나 도형을 가로지르는 아무 선분도 대각선이라고 생각한다','두 끝이 모두 꼭짓점인지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u4-X13','math',4,'u4',ARRAY['M4-2-u4-C7']::text[],'대각선의 수를 셀 때 한 꼭짓점에서 그은 것만 세거나, 같은 대각선을 두 번 센다','모든 꼭짓점에서, 겹친 것은 한 번') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u4-X14','math',4,'u4',ARRAY['M4-2-u4-C6','M4-2-u4-C7']::text[],'삼각형에도 대각선을 그을 수 있다고 생각한다','삼각형은 모든 꼭짓점이 이웃') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u4-X16','math',4,'u4',ARRAY['M4-2-u4-C8','M4-2-u4-C9']::text[],'조각을 겹치게 놓거나 빈틈을 남겨도 모양을 만들거나 채운 것이라고 생각한다','겹치지 않게, 빈틈없이') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u4-X17','math',4,'u4',ARRAY['M4-2-u4-C8','M4-2-u4-C10']::text[],'만든 도형의 이름을 쓴 조각의 수로 정하거나, 조각끼리 맞댄 안쪽 선까지 변으로 센다','바깥쪽 변만 세기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u4-X18','math',4,'u4',ARRAY['M4-2-u4-C8','M4-2-u4-C9','M4-2-u4-C10']::text[],'같은 모양을 만들거나 채우는 방법은 한 가지뿐이라고 생각한다 — 조각 수가 다르면 다른 모양이라고 한다','방법은 여러 가지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u4-X19','math',4,'u4',ARRAY['M4-2-u4-C8','M4-2-u4-C9']::text[],'모양 조각 사이의 크기 관계를 잘못 안다 — 사다리꼴은 정삼각형 2개, 정육각형은 정삼각형 4개라고 한다','정삼각형 몇 개로 덮이는지 확인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u4-X20','math',4,'u4',ARRAY['M4-2-u4-C1','M4-2-u4-C2','M4-2-u4-C3','M4-2-u4-C4','M4-2-u4-C5','M4-2-u4-C6','M4-2-u4-C7','M4-2-u4-C8','M4-2-u4-C9','M4-2-u4-C10']::text[],'묻는 말을 거꾸로 읽는다 — 아닌 것↔맞는 것, 잘못 말한↔바르게 말한','물음의 「아닌·잘못」에 동그라미') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u4-X21','math',4,'u4',ARRAY['M4-2-u4-C4']::text[],'이등변삼각형처럼 변의 길이와 각의 크기가 일부만 같아도 정다각형이라고 생각한다 — 두 변·두 각만 같은 도형을 정다각형이라고 한다','모든 변, 그리고 모든 각이 같은지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u4-X22','math',4,'u4',ARRAY['M4-2-u4-C4']::text[],'정다각형인 까닭을 「변의 수와 각의 수가 같아서」라고 댄다 — 변의 수와 각의 수는 어느 다각형이나 같다','변의 「길이」와 각의 「크기」를 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u4-X23','math',4,'u4',ARRAY['M4-2-u4-C8','M4-2-u4-C9','M4-2-u4-C10']::text[],'모양 조각의 이름을 잘못 말한다 — 사다리꼴·평행사변형 조각을 정삼각형·정사각형이라고 하거나 조각을 바꾸어 부른다','조각을 하나씩 짚으며 변의 수·길이로 이름 확인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u4-X24','math',4,'u4',ARRAY['M4-2-u4-C6']::text[],'서로 이웃하지 않는 두 꼭짓점을 곡선으로 이어도 대각선이라고 생각한다','대각선은 곧은 선분') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u4-X25','math',4,'u4',ARRAY['M4-2-u4-C4','M4-2-u4-C9']::text[],'정다각형이면 모두 평면을 빈틈없이 채울 수 있다고 생각한다 — 정오각형도 빈틈없이 채운다고 한다','한 꼭짓점에 모인 각이 360°가 되는지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u4_L02_basic#1','math',4,2,'u4','L02','tb_g4_2_math_u4_L02_basic','lesson_basic','M4-2-u4-C3',1,'sa','auto','준비하기 — 칠교판은 직각삼각형 모양 조각 5개, 정사각형 모양 조각 1개, 평행사변형 모양 조각 1개로 이루어져 있어요. 칠교판에서 사각형 모양 조각은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"M4-2-u4-C3","difficulty":1,"kind":"sa","stem":"준비하기 — 칠교판은 직각삼각형 모양 조각 5개, 정사각형 모양 조각 1개, 평행사변형 모양 조각 1개로 이루어져 있어요. 칠교판에서 사각형 모양 조각은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["변이 4개인 도형이 사각형이에요.","정사각형 조각 1개와 평행사변형 조각 1개가 변이 4개예요.","사각형 모양 조각은 모두 2개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u4_L02_basic#2','math',4,2,'u4','L02','tb_g4_2_math_u4_L02_basic','lesson_basic','M4-2-u4-C1',1,'blank','auto','준비하기 — 두 점을 곧게 이은 선을 □(이)라고 합니다. □에 알맞은 말은 무엇인가요?',ARRAY['M4-2-u4-X01','M4-2-u4-X06']::text[],true,'{"seq":2,"concept":"M4-2-u4-C1","difficulty":1,"kind":"blank","stem":"준비하기 — 두 점을 곧게 이은 선을 □(이)라고 합니다. □에 알맞은 말은 무엇인가요?","options":[{"t":"선분","correct":true},{"t":"직선","mis":"M4-2-u4-X01"},{"t":"곡선","mis":"M4-2-u4-X01"},{"t":"꼭짓점","mis":"M4-2-u4-X06"}],"explanation":["두 점을 곧게 이은 선이 선분이에요.","양쪽으로 끝없이 늘인 곧은 선은 직선, 굽은 선은 곡선이에요.","이번 단원의 다각형은 선분으로 둘러싸인 도형이에요."],"variant_rule":{"alt":[{"stem":"준비하기 — 세 변의 길이가 같은 삼각형을 □(이)라고 합니다. □에 알맞은 말은 무엇인가요?","options":[{"t":"정삼각형","correct":true},{"t":"이등변삼각형","mis":"M4-2-u4-X21"},{"t":"직각삼각형","mis":"M4-2-u4-X08"},{"t":"정사각형","mis":"M4-2-u4-X04"}],"explanation":["세 변의 길이가 모두 같은 삼각형이에요.","두 변의 길이만 같으면 이등변삼각형이에요.","□는 정삼각형이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u4_L02_basic#3','math',4,2,'u4','L02','tb_g4_2_math_u4_L02_basic','lesson_basic','M4-2-u4-C1',1,'mc','auto','『수학익힘』 준비 학습 — 선분을 찾아 고르세요.',ARRAY['M4-2-u4-X01']::text[],false,'{"seq":3,"concept":"M4-2-u4-C1","difficulty":1,"kind":"mc","stem":"『수학익힘』 준비 학습 — 선분을 찾아 고르세요.","options":[{"t":"㉰","correct":true},{"t":"㉮","mis":"M4-2-u4-X01"},{"t":"㉯","mis":"M4-2-u4-X01"},{"t":"㉮와 ㉰","mis":"M4-2-u4-X01"}],"explanation":["㉮는 굽은 선(곡선)이에요.","㉯는 양쪽으로 끝없이 늘인 직선이에요.","두 점을 곧게 이은 ㉰가 선분이에요."],"asset":{"type":"geo","items":[{"w":96,"h":80,"curve":[[[9.6,22.4],[86.4,22.4],[48.0,89.6]]]},{"w":96,"h":80,"pts":{"ㄱ":[32,40,"n"],"ㄴ":[64,40,"n"]},"line":[["ㄱ","ㄴ"]]},{"w":96,"h":80,"pts":{"ㄷ":[16,62],"ㄹ":[80,18]},"seg":[["ㄷ","ㄹ"]]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u4_L02_basic#4','math',4,2,'u4','L02','tb_g4_2_math_u4_L02_basic','lesson_basic','M4-2-u4-C1',1,'blank','auto','선분으로만 둘러싸인 도형을 □(이)라고 합니다. □에 알맞은 말은 무엇인가요?',ARRAY['M4-2-u4-X07','M4-2-u4-X11','M4-2-u4-X02']::text[],false,'{"seq":4,"concept":"M4-2-u4-C1","difficulty":1,"kind":"blank","stem":"선분으로만 둘러싸인 도형을 □(이)라고 합니다. □에 알맞은 말은 무엇인가요?","options":[{"t":"다각형","correct":true},{"t":"정다각형","mis":"M4-2-u4-X07"},{"t":"대각선","mis":"M4-2-u4-X11"},{"t":"평면도형","mis":"M4-2-u4-X02"}],"explanation":["여러 나라의 전통 가옥에서 찾은 도형을 선의 특징에 따라 나누어 봤어요.","선분으로만 둘러싸인 도형을 다각형이라고 해요.","정다각형은 다각형 가운데 변의 길이와 각의 크기가 모두 같은 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u4_L02_basic#5','math',4,2,'u4','L02','tb_g4_2_math_u4_L02_basic','lesson_basic','M4-2-u4-C1',2,'mc','auto','『수학』 86 — 여러 나라의 전통 가옥에서 찾은 도형이에요. 곡선이 포함된 도형을 모두 고르세요.',ARRAY['M4-2-u4-X01','M4-2-u4-X20']::text[],true,'{"seq":5,"concept":"M4-2-u4-C1","difficulty":2,"kind":"mc","stem":"『수학』 86 — 여러 나라의 전통 가옥에서 찾은 도형이에요. 곡선이 포함된 도형을 모두 고르세요.","options":[{"t":"가, 다, 라","correct":true},{"t":"라","mis":"M4-2-u4-X01"},{"t":"나, 마, 바","mis":"M4-2-u4-X20"},{"t":"가, 라","mis":"M4-2-u4-X01"}],"explanation":["도형을 이루는 선이 굽었는지 살펴봐요.","가와 다는 곡선과 선분으로, 라는 곡선으로만 이루어져 있어요.","곡선이 포함된 도형은 가, 다, 라예요."],"asset":{"type":"geo","items":[{"w":96,"h":80,"seg":[[[12.8,73.6],[83.2,73.6]]],"curve":[[[12.8,73.6],[83.2,73.6],[48.0,-48.0]]],"cap":"가"},{"w":96,"h":80,"poly":[[[9.6,12.8],[86.4,25.6],[86.4,60.8],[9.6,70.4]]],"cap":"나"},{"w":96,"h":80,"seg":[[[4.8,16.0],[22.4,64.0]],[[91.2,16.0],[73.6,64.0]]],"curve":[[[4.8,16.0],[91.2,16.0],[48.0,41.6]],[[22.4,64.0],[73.6,64.0],[48.0,86.4]]],"cap":"다"},{"w":96,"h":80,"circle":[[[48.0,40.0],33.6]],"cap":"라"},{"w":96,"h":80,"poly":[[[48.0,6.4],[70.4,73.6],[25.6,73.6]]],"cap":"마"},{"w":96,"h":80,"poly":[[[8.0,36.8],[48.0,6.4],[88.0,36.8],[88.0,73.6],[8.0,73.6]]],"cap":"바"}],"tag":false},"variant_rule":{"alt":[{"stem":"『수학』 86 — 여러 나라의 전통 가옥에서 찾은 도형이에요. 선분으로만 둘러싸인 도형을 모두 고르세요.","options":[{"t":"나, 마, 바","correct":true},{"t":"가, 나, 마, 바","mis":"M4-2-u4-X01"},{"t":"가, 다, 라","mis":"M4-2-u4-X20"},{"t":"나, 바","mis":"M4-2-u4-X03"}],"explanation":["곡선이 한 군데라도 있으면 빼요.","나, 마, 바는 선분으로만 둘러싸여 있어요(마는 삼각형도 다각형).","선분으로만 둘러싸인 도형은 나, 마, 바예요."],"asset":{"type":"geo","items":[{"w":96,"h":80,"seg":[[[12.8,73.6],[83.2,73.6]]],"curve":[[[12.8,73.6],[83.2,73.6],[48.0,-48.0]]],"cap":"가"},{"w":96,"h":80,"poly":[[[9.6,12.8],[86.4,25.6],[86.4,60.8],[9.6,70.4]]],"cap":"나"},{"w":96,"h":80,"seg":[[[4.8,16.0],[22.4,64.0]],[[91.2,16.0],[73.6,64.0]]],"curve":[[[4.8,16.0],[91.2,16.0],[48.0,41.6]],[[22.4,64.0],[73.6,64.0],[48.0,86.4]]],"cap":"다"},{"w":96,"h":80,"circle":[[[48.0,40.0],33.6]],"cap":"라"},{"w":96,"h":80,"poly":[[[48.0,6.4],[70.4,73.6],[25.6,73.6]]],"cap":"마"},{"w":96,"h":80,"poly":[[[8.0,36.8],[48.0,6.4],[88.0,36.8],[88.0,73.6],[8.0,73.6]]],"cap":"바"}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u4_L02_basic#6','math',4,2,'u4','L02','tb_g4_2_math_u4_L02_basic','lesson_basic','M4-2-u4-C1',2,'mc','auto','『수학』 87 — 다각형이 아닌 도형을 모두 고르세요.',ARRAY['M4-2-u4-X01','M4-2-u4-X20','M4-2-u4-X02']::text[],false,'{"seq":6,"concept":"M4-2-u4-C1","difficulty":2,"kind":"mc","stem":"『수학』 87 — 다각형이 아닌 도형을 모두 고르세요.","options":[{"t":"나, 라, 바","correct":true},{"t":"나, 바","mis":"M4-2-u4-X01"},{"t":"가, 다, 마","mis":"M4-2-u4-X20"},{"t":"라","mis":"M4-2-u4-X02"}],"explanation":["다각형은 선분으로만, 그리고 둘러싸여 있어야 해요.","나는 곡선으로 둘러싸였고, 바는 곡선이 포함되어 있고, 라는 열려 있어요.","다각형이 아닌 도형은 나, 라, 바예요."],"asset":{"type":"geo","items":[{"w":96,"h":80,"poly":[[[25.6,12.8],[89.6,12.8],[70.4,67.2],[6.4,67.2]]],"cap":"가"},{"w":96,"h":80,"oval":[[48,40.0,38.4,25.6]],"cap":"나"},{"w":96,"h":80,"poly":[[[32.0,9.6],[86.4,9.6],[86.4,70.4],[9.6,70.4],[9.6,32.0]]],"cap":"다"},{"w":96,"h":80,"seg":[[[48.0,8.0],[6.4,75.2]],[[22.4,72.0],[86.4,72.0]],[[86.4,72.0],[48.0,8.0]]],"cap":"라"},{"w":96,"h":80,"poly":[[[68.69,68.48],[27.31,68.48],[14.52,29.12],[48.0,4.8],[81.48,29.12]]],"cap":"마"},{"w":96,"h":80,"seg":[[[12.8,8.0],[12.8,72.0]],[[12.8,72.0],[76.8,72.0]]],"curve":[[[12.8,8.0],[76.8,72.0],[76.8,8.0]]],"cap":"바"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u4_L02_basic#7','math',4,2,'u4','L02','tb_g4_2_math_u4_L02_basic','lesson_basic','M4-2-u4-C1',2,'mc','auto','『수학』 87 — 라가 다각형이 아닌 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M4-2-u4-X03','M4-2-u4-X01','M4-2-u4-X02']::text[],true,'{"seq":7,"concept":"M4-2-u4-C1","difficulty":2,"kind":"mc","stem":"『수학』 87 — 라가 다각형이 아닌 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"선분으로 둘러싸여 있지 않고 열려 있으므로","correct":true},{"t":"변이 3개뿐이므로","mis":"M4-2-u4-X03"},{"t":"곡선이 포함되어 있으므로","mis":"M4-2-u4-X01"},{"t":"뾰족한 곳이 있으므로","mis":"M4-2-u4-X02"}],"explanation":["라는 선분으로만 그렸어요.","그런데 한 곳이 벌어져 선분으로 둘러싸여 있지 않아요.","열려 있으므로 다각형이 아니에요."],"asset":{"type":"geo","items":[{"w":96,"h":80,"seg":[[[48.0,8.0],[6.4,75.2]],[[22.4,72.0],[86.4,72.0]],[[86.4,72.0],[48.0,8.0]]],"cap":"라"}],"tag":false},"variant_rule":{"alt":[{"stem":"『수학』 87 — 나가 다각형이 아닌 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"곡선으로 둘러싸인 도형이므로","correct":true},{"t":"변이 너무 많으므로","mis":"M4-2-u4-X02"},{"t":"열려 있으므로","mis":"M4-2-u4-X01"},{"t":"크기가 크므로","mis":"M4-2-u4-X05"}],"explanation":["나는 굽은 선 하나로 둘러싸여 있어요.","다각형은 선분으로만 둘러싸인 도형이에요.","곡선으로 둘러싸인 도형이므로 다각형이 아니에요."],"asset":{"type":"geo","items":[{"w":96,"h":80,"oval":[[48,40.0,38.4,25.6]],"cap":"나"}],"tag":false}},{"stem":"『수학』 87 — 바가 다각형이 아닌 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"곡선이 포함된 도형이므로","correct":true},{"t":"열려 있으므로","mis":"M4-2-u4-X01"},{"t":"각이 2개뿐이므로","mis":"M4-2-u4-X02"},{"t":"선분이 2개뿐이므로","mis":"M4-2-u4-X03"}],"explanation":["바는 선분 2개와 곡선 1개로 둘러싸여 있어요.","곡선이 한 군데라도 섞이면 선분으로만 둘러싸인 도형이 아니에요.","곡선이 포함된 도형이므로 다각형이 아니에요."],"asset":{"type":"geo","items":[{"w":96,"h":80,"seg":[[[12.8,8.0],[12.8,72.0]],[[12.8,72.0],[76.8,72.0]]],"curve":[[[12.8,8.0],[76.8,72.0],[76.8,8.0]]],"cap":"바"}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u4_L02_basic#8','math',4,2,'u4','L02','tb_g4_2_math_u4_L02_basic','lesson_basic','M4-2-u4-C1',2,'mc','auto','『수학』 87 ④ — 생활 속에서 다각형 모양을 찾고 있어요. 다각형 모양이 아닌 것은 어느 것인가요?',ARRAY['M4-2-u4-X20']::text[],false,'{"seq":8,"concept":"M4-2-u4-C1","difficulty":2,"kind":"mc","stem":"『수학』 87 ④ — 생활 속에서 다각형 모양을 찾고 있어요. 다각형 모양이 아닌 것은 어느 것인가요?","options":[{"t":"원 모양 달고나","correct":true},{"t":"칠판","mis":"M4-2-u4-X20"},{"t":"어린이 보호 교통안전 표지판","mis":"M4-2-u4-X20"},{"t":"정지 교통안전 표지판","mis":"M4-2-u4-X20"}],"explanation":["칠판·교통안전 표지판은 선분으로만 둘러싸인 다각형 모양이에요.","원은 곡선으로 둘러싸여 있어요.","다각형 모양이 아닌 것은 원 모양 달고나예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u4_L02_basic#9','math',4,2,'u4','L02','tb_g4_2_math_u4_L02_basic','lesson_basic','M4-2-u4-C2',2,'mc','auto','『수학익힘』 준비 학습 — 도형에서 두 변이 만나는 점을 무엇이라고 하나요?',ARRAY['M4-2-u4-X06','M4-2-u4-X01','M4-2-u4-X11']::text[],true,'{"seq":9,"concept":"M4-2-u4-C2","difficulty":2,"kind":"mc","stem":"『수학익힘』 준비 학습 — 도형에서 두 변이 만나는 점을 무엇이라고 하나요?","options":[{"t":"꼭짓점","correct":true},{"t":"변","mis":"M4-2-u4-X06"},{"t":"선분","mis":"M4-2-u4-X01"},{"t":"대각선","mis":"M4-2-u4-X11"}],"explanation":["도형을 이루는 선분 하나하나가 변이에요.","두 변이 만나는 점이 꼭짓점이에요.","다각형은 변의 수와 꼭짓점의 수가 같아요."],"variant_rule":{"alt":[{"stem":"『수학익힘』 준비 학습 — 삼각형과 사각형을 둘러싼 선분 하나하나를 무엇이라고 하나요?","options":[{"t":"변","correct":true},{"t":"꼭짓점","mis":"M4-2-u4-X06"},{"t":"직선","mis":"M4-2-u4-X01"},{"t":"대각선","mis":"M4-2-u4-X11"}],"explanation":["도형을 둘러싼 선분이 변이에요.","변과 변이 만나는 점은 꼭짓점이에요.","선분 하나하나는 변이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u4_L02_basic#10','math',4,2,'u4','L02','tb_g4_2_math_u4_L02_basic','lesson_basic','M4-2-u4-C1',3,'match','auto','『수학』 86 — 도형에서 찾은 선의 특징과 도형을 알맞게 이으세요. 「다는 선분과 곡선으로 이루어져 있어.」 「라는 곡선으로만 이루어져 있어.」','{}'::text[],false,'{"seq":10,"concept":"M4-2-u4-C1","difficulty":3,"kind":"match","stem":"『수학』 86 — 도형에서 찾은 선의 특징과 도형을 알맞게 이으세요. 「다는 선분과 곡선으로 이루어져 있어.」 「라는 곡선으로만 이루어져 있어.」","pairs":[{"l":"선분으로만 이루어진 도형","r":"나, 마, 바"},{"l":"곡선과 선분으로 이루어진 도형","r":"가, 다"},{"l":"곡선으로만 이루어진 도형","r":"라"}],"mis":"M4-2-u4-X01","explanation":["도형마다 굽은 선과 곧은 선이 있는지 봐요.","나, 마, 바는 선분으로만, 가, 다는 곡선과 선분으로, 라는 곡선으로만 이루어져 있어요.","선분으로만 둘러싸인 나, 마, 바가 다각형이에요."],"asset":{"type":"geo","items":[{"w":96,"h":80,"seg":[[[12.8,73.6],[83.2,73.6]]],"curve":[[[12.8,73.6],[83.2,73.6],[48.0,-48.0]]],"cap":"가"},{"w":96,"h":80,"poly":[[[9.6,12.8],[86.4,25.6],[86.4,60.8],[9.6,70.4]]],"cap":"나"},{"w":96,"h":80,"seg":[[[4.8,16.0],[22.4,64.0]],[[91.2,16.0],[73.6,64.0]]],"curve":[[[4.8,16.0],[91.2,16.0],[48.0,41.6]],[[22.4,64.0],[73.6,64.0],[48.0,86.4]]],"cap":"다"},{"w":96,"h":80,"circle":[[[48.0,40.0],33.6]],"cap":"라"},{"w":96,"h":80,"poly":[[[48.0,6.4],[70.4,73.6],[25.6,73.6]]],"cap":"마"},{"w":96,"h":80,"poly":[[[8.0,36.8],[48.0,6.4],[88.0,36.8],[88.0,73.6],[8.0,73.6]]],"cap":"바"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u4_L02_challenge#1','math',4,2,'u4','L02','tb_g4_2_math_u4_L02_challenge','lesson_challenge','M4-2-u4-C1',2,'mc','auto','단원 도입 — 「이건 삼각형 모양, 저건 사각형 모양이네. 나머지 도형들도 이름이 있을까?」 단원 핵심 질문의 △, □, 오각형, 육각형 모양의 공통점은 어느 것인가요?',ARRAY['M4-2-u4-X04','M4-2-u4-X05','M4-2-u4-X01']::text[],false,'{"seq":1,"concept":"M4-2-u4-C1","difficulty":2,"kind":"mc","stem":"단원 도입 — 「이건 삼각형 모양, 저건 사각형 모양이네. 나머지 도형들도 이름이 있을까?」 단원 핵심 질문의 △, □, 오각형, 육각형 모양의 공통점은 어느 것인가요?","options":[{"t":"모두 선분으로만 둘러싸여 있다","correct":true},{"t":"변의 수가 모두 같다","mis":"M4-2-u4-X04"},{"t":"크기가 모두 같다","mis":"M4-2-u4-X05"},{"t":"모두 곡선이 있다","mis":"M4-2-u4-X01"}],"explanation":["네 도형을 이루는 선을 살펴봐요.","변의 수는 3, 4, 5, 6개로 다르지만 모두 선분으로만 둘러싸여 있어요.","선분으로만 둘러싸인 도형은 모두 다각형이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u4_L02_challenge#2','math',4,2,'u4','L02','tb_g4_2_math_u4_L02_challenge','lesson_challenge','M4-2-u4-C1',2,'ox','auto','「선분이 있는 평면도형은 다각형이야.」라는 지아의 말은 맞아요.',ARRAY['M4-2-u4-X01']::text[],false,'{"seq":2,"concept":"M4-2-u4-C1","difficulty":2,"kind":"ox","stem":"「선분이 있는 평면도형은 다각형이야.」라는 지아의 말은 맞아요.","answer":"X","reason_options":[{"t":"곡선이 섞이거나 열려 있으면 선분이 있어도 다각형이 아니라서","correct":true},{"t":"선분이 하나라도 있으면 다각형이라서","mis":"M4-2-u4-X01"}],"mis":"M4-2-u4-X01","explanation":["다각형은 선분으로만 이루어져야 해요.","그리고 선분으로 둘러싸여(닫혀) 있어야 해요.","선분이 있는 도형이라도 두 조건을 다 갖추어야 다각형이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u4_L02_challenge#3','math',4,2,'u4','L02','tb_g4_2_math_u4_L02_challenge','lesson_challenge','M4-2-u4-C1',3,'mc','auto','『수학익힘』 54 — 나라마다 전통 가옥의 모양이 달라요. 가옥에서 찾은 도형이 가 이글루(둥근 모양), 나 한옥(지붕 끝이 휘어 올라감), 다 원뿔 모양 천막(삼각형 모양), 라 통나무집(오각형 모양)일 때, 다각형은 어느 것인가요?',ARRAY['M4-2-u4-X20','M4-2-u4-X01','M4-2-u4-X03']::text[],false,'{"seq":3,"concept":"M4-2-u4-C1","difficulty":3,"kind":"mc","stem":"『수학익힘』 54 — 나라마다 전통 가옥의 모양이 달라요. 가옥에서 찾은 도형이 가 이글루(둥근 모양), 나 한옥(지붕 끝이 휘어 올라감), 다 원뿔 모양 천막(삼각형 모양), 라 통나무집(오각형 모양)일 때, 다각형은 어느 것인가요?","options":[{"t":"다, 라","correct":true},{"t":"가, 나","mis":"M4-2-u4-X20"},{"t":"나, 다, 라","mis":"M4-2-u4-X01"},{"t":"라","mis":"M4-2-u4-X03"}],"explanation":["선분으로만 둘러싸인 도형을 찾아요.","가는 곡선으로, 나는 휘어진 곡선이 섞여 있어요.","선분으로만 둘러싸인 다, 라가 다각형이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u4_L02_challenge#4','math',4,2,'u4','L02','tb_g4_2_math_u4_L02_challenge','lesson_challenge','M4-2-u4-C1',3,'mc','auto','『수학익힘』 54 ① — 다각형을 모두 고르세요.',ARRAY['M4-2-u4-X01','M4-2-u4-X20']::text[],false,'{"seq":4,"concept":"M4-2-u4-C1","difficulty":3,"kind":"mc","stem":"『수학익힘』 54 ① — 다각형을 모두 고르세요.","options":[{"t":"가, 다, 바","correct":true},{"t":"가, 다, 라, 바","mis":"M4-2-u4-X01"},{"t":"가, 다, 마, 바","mis":"M4-2-u4-X01"},{"t":"나, 라, 마","mis":"M4-2-u4-X20"}],"explanation":["나와 마는 곡선이 섞여 있어요.","라는 선분으로만 그렸지만 한 곳이 열려 있어요.","선분으로만 둘러싸인 가, 다, 바가 다각형이에요."],"asset":{"type":"geo","items":[{"w":96,"h":80,"poly":[[[87.39,34.45],[48.0,8.0],[13.36,24.0],[10.42,50.94],[34.32,70.06],[78.64,60.58]]],"cap":"가"},{"w":96,"h":80,"seg":[[[9.6,16.0],[86.4,16.0]]],"curve":[[[9.6,16.0],[86.4,16.0],[48.0,96.0]]],"cap":"나"},{"w":96,"h":80,"poly":[[[63.27,71.71],[32.73,71.71],[13.68,47.83],[20.48,18.05],[48.0,4.8],[75.52,18.05],[82.32,47.83]]],"cap":"다"},{"w":96,"h":80,"seg":[[[8.0,73.6],[28.8,8.0]],[[28.8,8.0],[88.0,8.0]],[[88.0,8.0],[67.2,72.0]],[[67.2,72.0],[38.4,72.0]]],"cap":"라"},{"w":96,"h":80,"seg":[[[16.0,16.0],[16.0,64.0]],[[80.0,16.0],[80.0,64.0]]],"curve":[[[16.0,16.0],[80.0,16.0],[48.0,35.2]],[[16.0,64.0],[80.0,64.0],[48.0,86.4]]],"cap":"마"},{"w":96,"h":80,"poly":[[[61.47,72.52],[34.53,72.52],[15.48,53.47],[15.48,26.53],[34.53,7.48],[61.47,7.48],[80.52,26.53],[80.52,53.47]]],"cap":"바"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u4_L02_challenge#5','math',4,2,'u4','L02','tb_g4_2_math_u4_L02_challenge','lesson_challenge','M4-2-u4-C1',3,'error','auto','『수학익힘』 55 수학에 퐁당 — 다각형에 대해 잘못 설명한 사람은 누구인가요?',ARRAY['M4-2-u4-X01','M4-2-u4-X20','M4-2-u4-X03']::text[],false,'{"seq":5,"concept":"M4-2-u4-C1","difficulty":3,"kind":"error","stem":"『수학익힘』 55 수학에 퐁당 — 다각형에 대해 잘못 설명한 사람은 누구인가요?","options":[{"t":"지아 — 「선분이 있는 평면도형은 다각형이야.」","correct":true,"mis_target":"M4-2-u4-X01"},{"t":"정후 — 「원은 다각형이 아니야.」","mis":"M4-2-u4-X20"},{"t":"서윤 — 「이등변삼각형은 다각형이야.」","mis":"M4-2-u4-X03"}],"explanation":["원은 곡선으로 둘러싸여 다각형이 아니에요.","이등변삼각형은 선분 3개로 둘러싸인 다각형이에요.","선분이 있어도 선분으로만 둘러싸여야 다각형이므로 지아가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u4_L02_challenge#6','math',4,2,'u4','L02','tb_g4_2_math_u4_L02_challenge','lesson_challenge','M4-2-u4-C1',3,'ox','auto','『수학익힘』 55 ④ — 하트 모양은 뾰족한 곳이 있으므로 다각형이에요.',ARRAY['M4-2-u4-X02']::text[],false,'{"seq":6,"concept":"M4-2-u4-C1","difficulty":3,"kind":"ox","stem":"『수학익힘』 55 ④ — 하트 모양은 뾰족한 곳이 있으므로 다각형이에요.","answer":"X","reason_options":[{"t":"선분으로 둘러싸여 있지 않아서","correct":true},{"t":"각이 있는 도형은 다각형이라서","mis":"M4-2-u4-X02"}],"mis":"M4-2-u4-X02","explanation":["하트 모양은 굽은 선(곡선)으로 둘러싸여 있어요.","뾰족한 곳(각)이 있는지가 아니라 선분으로만 둘러싸였는지를 봐요.","선분으로 둘러싸여 있지 않으므로 다각형이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u4_L02_challenge#7','math',4,2,'u4','L02','tb_g4_2_math_u4_L02_challenge','lesson_challenge','M4-2-u4-C1',3,'sa','auto','지도서 334 — 선분 2개로는 도형을 둘러쌀 수 없어요. 다각형이 되려면 선분이 적어도 몇 개 있어야 하나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"M4-2-u4-C1","difficulty":3,"kind":"sa","stem":"지도서 334 — 선분 2개로는 도형을 둘러쌀 수 없어요. 다각형이 되려면 선분이 적어도 몇 개 있어야 하나요? 숫자로 쓰세요.","answer":["3"],"explanation":["선분 2개는 어떻게 놓아도 한쪽이 열려 있어요.","선분 3개면 삼각형처럼 둘러쌀 수 있어요.","적어도 3개 — 삼각형도 다각형이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u4_L02_challenge#8','math',4,2,'u4','L02','tb_g4_2_math_u4_L02_challenge','lesson_challenge','M4-2-u4-C1',4,'mc','auto','『수학』 86 — 가~바 가운데 뾰족한 곳(각)이 있는데도 다각형이 아닌 도형을 모두 고르세요.',ARRAY['M4-2-u4-X02','M4-2-u4-X20']::text[],false,'{"seq":8,"concept":"M4-2-u4-C1","difficulty":4,"kind":"mc","stem":"『수학』 86 — 가~바 가운데 뾰족한 곳(각)이 있는데도 다각형이 아닌 도형을 모두 고르세요.","options":[{"t":"가, 다","correct":true},{"t":"가, 다, 라","mis":"M4-2-u4-X02"},{"t":"나, 마, 바","mis":"M4-2-u4-X20"},{"t":"다","mis":"M4-2-u4-X02"}],"explanation":["가와 다는 아래쪽에 뾰족한 곳이 있어요.","하지만 둘 다 곡선이 섞여 있어 선분으로만 둘러싸인 도형이 아니에요.","각이 있어도 다각형이 아닌 도형은 가, 다 — 각이 아니라 변을 봐요."],"asset":{"type":"geo","items":[{"w":96,"h":80,"seg":[[[12.8,73.6],[83.2,73.6]]],"curve":[[[12.8,73.6],[83.2,73.6],[48.0,-48.0]]],"cap":"가"},{"w":96,"h":80,"poly":[[[9.6,12.8],[86.4,25.6],[86.4,60.8],[9.6,70.4]]],"cap":"나"},{"w":96,"h":80,"seg":[[[4.8,16.0],[22.4,64.0]],[[91.2,16.0],[73.6,64.0]]],"curve":[[[4.8,16.0],[91.2,16.0],[48.0,41.6]],[[22.4,64.0],[73.6,64.0],[48.0,86.4]]],"cap":"다"},{"w":96,"h":80,"circle":[[[48.0,40.0],33.6]],"cap":"라"},{"w":96,"h":80,"poly":[[[48.0,6.4],[70.4,73.6],[25.6,73.6]]],"cap":"마"},{"w":96,"h":80,"poly":[[[8.0,36.8],[48.0,6.4],[88.0,36.8],[88.0,73.6],[8.0,73.6]]],"cap":"바"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u4_L02_challenge#9','math',4,2,'u4','L02','tb_g4_2_math_u4_L02_challenge','lesson_challenge','M4-2-u4-C2',4,'sa','auto','『수학』 87 — 가~바 가운데 다각형을 모두 찾아, 다각형인 도형의 변의 수를 모두 더하면 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"M4-2-u4-C2","difficulty":4,"kind":"sa","stem":"『수학』 87 — 가~바 가운데 다각형을 모두 찾아, 다각형인 도형의 변의 수를 모두 더하면 몇 개인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["다각형은 가, 다, 마예요(나·바는 곡선, 라는 열림).","가는 변 4개, 다는 변 5개, 마는 변 5개예요.","4 + 5 + 5 = 14개예요."],"asset":{"type":"geo","items":[{"w":96,"h":80,"poly":[[[25.6,12.8],[89.6,12.8],[70.4,67.2],[6.4,67.2]]],"cap":"가"},{"w":96,"h":80,"oval":[[48,40.0,38.4,25.6]],"cap":"나"},{"w":96,"h":80,"poly":[[[32.0,9.6],[86.4,9.6],[86.4,70.4],[9.6,70.4],[9.6,32.0]]],"cap":"다"},{"w":96,"h":80,"seg":[[[48.0,8.0],[6.4,75.2]],[[22.4,72.0],[86.4,72.0]],[[86.4,72.0],[48.0,8.0]]],"cap":"라"},{"w":96,"h":80,"poly":[[[68.69,68.48],[27.31,68.48],[14.52,29.12],[48.0,4.8],[81.48,29.12]]],"cap":"마"},{"w":96,"h":80,"seg":[[[12.8,8.0],[12.8,72.0]],[[12.8,72.0],[76.8,72.0]]],"curve":[[[12.8,8.0],[76.8,72.0],[76.8,8.0]]],"cap":"바"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u4_L02_challenge#10','math',4,2,'u4','L02','tb_g4_2_math_u4_L02_challenge','lesson_challenge','M4-2-u4-C1',4,'essay','teacher','『수학』 87 — 나, 라, 바가 다각형이 아닌 까닭을 각각 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M4-2-u4-C1","difficulty":4,"kind":"essay","stem":"『수학』 87 — 나, 라, 바가 다각형이 아닌 까닭을 각각 써 보세요.","answer_guide":{"answer":"예: 나는 곡선으로 둘러싸인 도형이므로 다각형이 아니다. 라는 선분으로 둘러싸여 있지 않고 열려 있으므로 다각형이 아니다. 바는 곡선이 포함된 도형이므로 다각형이 아니다.","scoring_points":["나 — 곡선으로 둘러싸였다고 썼는가","라 — 둘러싸여 있지 않고 열려 있다고 썼는가","바 — 곡선이 포함되었다고 썼는가"]},"explanation":["다각형은 선분으로만 둘러싸인 도형이에요.","「선분으로만」을 어긴 것은 나, 바예요.","「둘러싸인」을 어긴 것은 라예요."],"asset":{"type":"geo","items":[{"w":96,"h":80,"oval":[[48,40.0,38.4,25.6]],"cap":"나"},{"w":96,"h":80,"seg":[[[48.0,8.0],[6.4,75.2]],[[22.4,72.0],[86.4,72.0]],[[86.4,72.0],[48.0,8.0]]],"cap":"라"},{"w":96,"h":80,"seg":[[[12.8,8.0],[12.8,72.0]],[[12.8,72.0],[76.8,72.0]]],"curve":[[[12.8,8.0],[76.8,72.0],[76.8,8.0]]],"cap":"바"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u4_L03_basic#1','math',4,2,'u4','L03','tb_g4_2_math_u4_L03_basic','lesson_basic','M4-2-u4-C3',1,'blank','auto','다각형은 변의 수에 따라 이름을 붙여요. 변이 6개인 다각형을 □(이)라고 합니다. □에 알맞은 말은 무엇인가요?',ARRAY['M4-2-u4-X04','M4-2-u4-X07']::text[],true,'{"seq":1,"concept":"M4-2-u4-C3","difficulty":1,"kind":"blank","stem":"다각형은 변의 수에 따라 이름을 붙여요. 변이 6개인 다각형을 □(이)라고 합니다. □에 알맞은 말은 무엇인가요?","options":[{"t":"육각형","correct":true},{"t":"오각형","mis":"M4-2-u4-X04"},{"t":"칠각형","mis":"M4-2-u4-X04"},{"t":"정육각형","mis":"M4-2-u4-X07"}],"explanation":["다각형의 이름은 변의 수로 정해요.","변이 5개이면 오각형, 6개이면 육각형, 7개이면 칠각형, 8개이면 팔각형이에요.","변이 6개이니 육각형이에요."],"variant_rule":{"alt":[{"stem":"다각형은 변의 수에 따라 이름을 붙여요. 변이 7개인 다각형을 □(이)라고 합니다. □에 알맞은 말은 무엇인가요?","options":[{"t":"칠각형","correct":true},{"t":"육각형","mis":"M4-2-u4-X04"},{"t":"팔각형","mis":"M4-2-u4-X04"},{"t":"정칠각형","mis":"M4-2-u4-X07"}],"explanation":["다각형의 이름은 변의 수로 정해요.","변이 7개이면 칠각형이에요.","□는 칠각형이에요."]},{"stem":"다각형은 변의 수에 따라 이름을 붙여요. 변이 8개인 다각형을 □(이)라고 합니다. □에 알맞은 말은 무엇인가요?","options":[{"t":"팔각형","correct":true},{"t":"칠각형","mis":"M4-2-u4-X04"},{"t":"육각형","mis":"M4-2-u4-X04"},{"t":"정팔각형","mis":"M4-2-u4-X07"}],"explanation":["다각형의 이름은 변의 수로 정해요.","변이 8개이면 팔각형이에요.","□는 팔각형이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u4_L03_basic#2','math',4,2,'u4','L03','tb_g4_2_math_u4_L03_basic','lesson_basic','M4-2-u4-C2',1,'sa','auto','『수학』 88 ⑤ — 다각형 가의 변은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M4-2-u4-C2","difficulty":1,"kind":"sa","stem":"『수학』 88 ⑤ — 다각형 가의 변은 몇 개인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["한 꼭짓점에서 시작해 한 방향으로 돌며 변에 표시해요.","빠뜨리거나 두 번 세지 않게 끝까지 세요.","가의 변은 5개 — 오각형이에요."],"asset":{"type":"geo","items":[{"w":96,"h":80,"poly":[[[87.39,34.45],[48.0,8.0],[8.61,34.45],[25.06,66.21],[70.94,66.21]]],"cap":"가"}],"tag":false},"variant_rule":{"alt":[{"stem":"『수학』 88 ⑤ — 다각형 나의 변은 몇 개인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["한 꼭짓점에서 시작해 표시하며 세요.","빠뜨리거나 두 번 세지 않게 끝까지 세요.","나의 변은 8개 — 팔각형이에요."],"asset":{"type":"geo","items":[{"w":96,"h":80,"poly":[[[88.0,40.0],[78.64,19.42],[44.51,8.13],[19.71,17.38],[8.0,40.0],[17.36,60.58],[48.0,72.0],[76.29,62.62]]],"cap":"나"}],"tag":false}},{"stem":"『수학』 88 ⑤ — 다각형 라의 변은 몇 개인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["한 꼭짓점에서 시작해 표시하며 세요.","빠뜨리거나 두 번 세지 않게 끝까지 세요.","라의 변은 7개 — 칠각형이에요."],"asset":{"type":"geo","items":[{"w":96,"h":80,"poly":[[[88.0,40.0],[73.71,15.49],[41.06,8.48],[13.36,24.0],[10.42,50.94],[37.65,70.91],[70.94,66.21]]],"cap":"라"}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u4_L03_basic#3','math',4,2,'u4','L03','tb_g4_2_math_u4_L03_basic','lesson_basic','M4-2-u4-C3',1,'mc','auto','『수학』 89 ⑦ — 다각형의 이름을 써 보아요. 이 다각형의 이름은 무엇인가요?',ARRAY['M4-2-u4-X04']::text[],true,'{"seq":3,"concept":"M4-2-u4-C3","difficulty":1,"kind":"mc","stem":"『수학』 89 ⑦ — 다각형의 이름을 써 보아요. 이 다각형의 이름은 무엇인가요?","options":[{"t":"칠각형","correct":true},{"t":"육각형","mis":"M4-2-u4-X04"},{"t":"팔각형","mis":"M4-2-u4-X04"},{"t":"구각형","mis":"M4-2-u4-X04"}],"explanation":["변을 세어 봐요.","변이 7개 있어요.","변이 7개이므로 칠각형이에요."],"asset":{"type":"geo","items":[{"w":96,"h":80,"poly":[[[88.98,34.45],[65.58,10.99],[30.42,10.99],[7.82,31.71],[13.92,58.35],[48.0,72.0],[79.87,60.58]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 『수학』 89 ⑦ — 다각형의 이름을 써 보아요. 이 다각형의 이름은 무엇인가요?","options":[{"t":"팔각형","correct":true},{"t":"칠각형","mis":"M4-2-u4-X04"},{"t":"구각형","mis":"M4-2-u4-X04"},{"t":"십각형","mis":"M4-2-u4-X04"}],"explanation":["변을 세어 봐요.","변이 8개 있어요.","변이 8개이므로 팔각형이에요."],"asset":{"type":"geo","items":[{"w":96,"h":80,"poly":[[[88.59,30.14],[69.6,15.06],[26.4,15.06],[7.41,30.14],[7.41,49.86],[26.4,64.94],[69.6,64.94],[88.59,49.86]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u4_L03_basic#4','math',4,2,'u4','L03','tb_g4_2_math_u4_L03_basic','lesson_basic','M4-2-u4-C2',1,'sa','auto','『수학』 89 ⑥ — 색종이를 잘라 칠각형을 만들었어요. 만든 칠각형의 꼭짓점은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M4-2-u4-C2","difficulty":1,"kind":"sa","stem":"『수학』 89 ⑥ — 색종이를 잘라 칠각형을 만들었어요. 만든 칠각형의 꼭짓점은 몇 개인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["칠각형은 변이 7개예요.","다각형은 변의 수와 꼭짓점의 수가 같아요.","칠각형의 꼭짓점은 7개예요."],"variant_rule":{"alt":[{"stem":"『수학』 89 ⑥ — 도형판에 육각형을 만들었어요. 만든 육각형의 꼭짓점은 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["육각형은 변이 6개예요.","변의 수와 꼭짓점의 수는 같아요.","육각형의 꼭짓점은 6개예요."]},{"stem":"『수학』 89 ⑥ — 도형판에 팔각형을 만들었어요. 만든 팔각형의 꼭짓점은 몇 개인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["팔각형은 변이 8개예요.","변의 수와 꼭짓점의 수는 같아요.","팔각형의 꼭짓점은 8개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u4_L03_basic#5','math',4,2,'u4','L03','tb_g4_2_math_u4_L03_basic','lesson_basic','M4-2-u4-C3',2,'mc','auto','『수학』 88 ⑤ — 변의 수에 따라 다각형을 분류해요. 변이 6개인 다각형을 모두 고르세요.',ARRAY['M4-2-u4-X04']::text[],true,'{"seq":5,"concept":"M4-2-u4-C3","difficulty":2,"kind":"mc","stem":"『수학』 88 ⑤ — 변의 수에 따라 다각형을 분류해요. 변이 6개인 다각형을 모두 고르세요.","options":[{"t":"다, 바","correct":true},{"t":"다, 라","mis":"M4-2-u4-X04"},{"t":"바","mis":"M4-2-u4-X04"},{"t":"라, 사","mis":"M4-2-u4-X04"}],"explanation":["도형마다 변을 표시하며 세요.","다와 바는 변이 6개, 라와 사는 7개예요.","변이 6개인 다각형은 다, 바 — 육각형이에요."],"asset":{"type":"geo","items":[{"w":96,"h":80,"poly":[[[87.39,34.45],[48.0,8.0],[8.61,34.45],[25.06,66.21],[70.94,66.21]]],"cap":"가"},{"w":96,"h":80,"poly":[[[88.0,40.0],[78.64,19.42],[44.51,8.13],[19.71,17.38],[8.0,40.0],[17.36,60.58],[48.0,72.0],[76.29,62.62]]],"cap":"나"},{"w":96,"h":80,"poly":[[[85.58,29.06],[54.94,8.48],[10.42,29.06],[10.42,50.94],[41.06,71.52],[82.64,56.0]]],"cap":"다"},{"w":96,"h":80,"poly":[[[88.0,40.0],[73.71,15.49],[41.06,8.48],[13.36,24.0],[10.42,50.94],[37.65,70.91],[70.94,66.21]]],"cap":"라"},{"w":96,"h":80,"poly":[[[86.64,31.71],[68.0,12.29],[41.06,8.48],[13.36,24.0],[8.61,45.55],[28.0,67.71],[54.94,71.52],[82.64,56.0]]],"cap":"마"},{"w":96,"h":80,"poly":[[[88.0,40.0],[61.68,9.94],[28.0,12.29],[8.0,40.0],[28.0,67.71],[68.0,67.71]]],"cap":"바"},{"w":96,"h":80,"poly":[[[84.26,26.48],[58.35,9.09],[22.29,15.49],[8.0,40.0],[17.36,60.58],[48.0,72.0],[78.64,60.58]]],"cap":"사"}],"tag":false},"variant_rule":{"alt":[{"stem":"『수학』 88 ⑤ — 변의 수에 따라 다각형을 분류해요. 변이 7개인 다각형을 모두 고르세요.","options":[{"t":"라, 사","correct":true},{"t":"마, 사","mis":"M4-2-u4-X04"},{"t":"라","mis":"M4-2-u4-X04"},{"t":"다, 바","mis":"M4-2-u4-X04"}],"explanation":["도형마다 변을 표시하며 세요.","라와 사는 변이 7개, 마는 8개예요.","변이 7개인 다각형은 라, 사 — 칠각형이에요."],"asset":{"type