INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u4_L03_basic#6','math',4,2,'u4','L03','tb_g4_2_math_u4_L03_basic','lesson_basic','M4-2-u4-C3',2,'match','auto','『수학익힘』 55 ③ — 알맞은 이름을 찾아 이으세요.','{}'::text[],false,'{"seq":6,"concept":"M4-2-u4-C3","difficulty":2,"kind":"match","stem":"『수학익힘』 55 ③ — 알맞은 이름을 찾아 이으세요.","pairs":[{"l":"㉮","r":"팔각형"},{"l":"㉯","r":"오각형"},{"l":"㉰","r":"칠각형"}],"mis":"M4-2-u4-X04","explanation":["도형마다 변을 세어요.","㉮는 변 8개, ㉯는 변 5개, ㉰는 변 7개예요.","㉮ 팔각형, ㉯ 오각형, ㉰ 칠각형이에요."],"asset":{"type":"geo","items":[{"w":96,"h":80,"poly":[[[82.0,27.14],[62.08,8.96],[33.92,8.96],[14.0,27.14],[14.0,52.86],[33.92,71.04],[62.08,71.04],[82.0,52.86]]]},{"w":96,"h":80,"poly":[[[84.53,29.12],[48.0,4.8],[11.47,29.12],[25.42,68.48],[70.58,68.48]]]},{"w":96,"h":80,"poly":[[[76.77,19.06],[48.0,6.4],[19.23,19.06],[12.13,47.47],[32.03,70.27],[63.97,70.27],[83.87,47.47]]]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u4_L03_basic#7','math',4,2,'u4','L03','tb_g4_2_math_u4_L03_basic','lesson_basic','M4-2-u4-C3',2,'mc','auto','『수학익힘』 55 ⑤ — 어린이 보호 교통안전 표지판은 어떤 다각형 모양인가요?',ARRAY['M4-2-u4-X04']::text[],true,'{"seq":7,"concept":"M4-2-u4-C3","difficulty":2,"kind":"mc","stem":"『수학익힘』 55 ⑤ — 어린이 보호 교통안전 표지판은 어떤 다각형 모양인가요?","options":[{"t":"오각형","correct":true},{"t":"사각형","mis":"M4-2-u4-X04"},{"t":"육각형","mis":"M4-2-u4-X04"},{"t":"삼각형","mis":"M4-2-u4-X04"}],"explanation":["표지판의 변을 세어요.","변이 5개예요.","변이 5개이므로 오각형 모양이에요."],"asset":{"type":"geo","items":[{"w":96,"h":80,"poly":[[[48.0,6.4],[86.4,35.2],[86.4,73.6],[9.6,73.6],[9.6,35.2]]],"cap":"어린이 보호"}],"tag":false},"variant_rule":{"alt":[{"stem":"『수학익힘』 55 ⑤ — 정지 교통안전 표지판은 어떤 다각형 모양인가요?","options":[{"t":"팔각형","correct":true},{"t":"칠각형","mis":"M4-2-u4-X04"},{"t":"육각형","mis":"M4-2-u4-X04"},{"t":"구각형","mis":"M4-2-u4-X04"}],"explanation":["표지판의 변을 세어요.","변이 8개예요.","변이 8개이므로 팔각형 모양이에요."],"asset":{"type":"geo","items":[{"w":96,"h":80,"poly":[[[61.47,72.52],[34.53,72.52],[15.48,53.47],[15.48,26.53],[34.53,7.48],[61.47,7.48],[80.52,26.53],[80.52,53.47]]],"cap":"정지"}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u4_L03_basic#8','math',4,2,'u4','L03','tb_g4_2_math_u4_L03_basic','lesson_basic','M4-2-u4-C2',2,'ox','auto','『수학』 89 — 육각형·칠각형·팔각형의 표를 보고 알게 된 점이에요. 「다각형의 이름이 같으면 변의 수와 꼭짓점의 수가 같아요.」',ARRAY['M4-2-u4-X06']::text[],false,'{"seq":8,"concept":"M4-2-u4-C2","difficulty":2,"kind":"ox","stem":"『수학』 89 — 육각형·칠각형·팔각형의 표를 보고 알게 된 점이에요. 「다각형의 이름이 같으면 변의 수와 꼭짓점의 수가 같아요.」","answer":"O","reason_options":[{"t":"육각형은 변·꼭짓점이 6개씩, 칠각형은 7개씩, 팔각형은 8개씩이라서","correct":true},{"t":"꼭짓점은 언제나 변보다 하나 더 많아서","mis":"M4-2-u4-X06"}],"mis":"M4-2-u4-X06","explanation":["표: 육각형 변 6개·꼭짓점 6개, 칠각형 7개·7개, 팔각형 8개·8개.","변과 변이 만나는 곳마다 꼭짓점이 하나씩 생겨요.","그래서 다각형의 변의 수와 꼭짓점의 수는 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u4_L03_basic#9','math',4,2,'u4','L03','tb_g4_2_math_u4_L03_basic','lesson_basic','M4-2-u4-C3',2,'mc','auto','『수학』 89 재미있는 수학 — 다각형 카드를 한 장 뽑은 친구가 「변이 5개야.」라고 설명했어요. 도형판에 만들어야 할 다각형의 이름은 무엇인가요?',ARRAY['M4-2-u4-X04','M4-2-u4-X07']::text[],false,'{"seq":9,"concept":"M4-2-u4-C3","difficulty":2,"kind":"mc","stem":"『수학』 89 재미있는 수학 — 다각형 카드를 한 장 뽑은 친구가 「변이 5개야.」라고 설명했어요. 도형판에 만들어야 할 다각형의 이름은 무엇인가요?","options":[{"t":"오각형","correct":true},{"t":"사각형","mis":"M4-2-u4-X04"},{"t":"육각형","mis":"M4-2-u4-X04"},{"t":"정오각형","mis":"M4-2-u4-X07"}],"explanation":["친구의 설명은 변의 수예요.","변이 5개인 다각형은 오각형이에요.","변의 길이가 모두 같을 필요는 없어요 — 오각형이면 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u4_L03_basic#10','math',4,2,'u4','L03','tb_g4_2_math_u4_L03_basic','lesson_basic','M4-2-u4-C3',3,'ox','auto','『수학』 88 ⑥ — 색종이를 잘라 만든 육각형과 도형판에 만든 육각형은 변의 길이와 모양, 크기가 서로 달라요. 그래도 둘 다 육각형이에요.',ARRAY['M4-2-u4-X05']::text[],false,'{"seq":10,"concept":"M4-2-u4-C3","difficulty":3,"kind":"ox","stem":"『수학』 88 ⑥ — 색종이를 잘라 만든 육각형과 도형판에 만든 육각형은 변의 길이와 모양, 크기가 서로 달라요. 그래도 둘 다 육각형이에요.","answer":"O","reason_options":[{"t":"변이 6개이면 모양과 크기에 상관없이 육각형이라서","correct":true},{"t":"모양이 다르면 이름도 달라서","mis":"M4-2-u4-X05"}],"mis":"M4-2-u4-X05","explanation":["다각형의 이름은 변의 수로만 정해요.","두 도형 모두 변이 6개예요.","모양·크기·변의 길이가 달라도 둘 다 육각형이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u4_L03_challenge#1','math',4,2,'u4','L03','tb_g4_2_math_u4_L03_challenge','lesson_challenge','M4-2-u4-C3',2,'mc','auto','지도서 336 — 한 친구가 『수학』 88 ⑤의 다각형을 「5개: 가 / 6개: 다, 라 / 7개: 마, 사 / 8개: 나, 바」로 분류했어요. 잘못 넣은 다각형을 모두 고르세요.',ARRAY['M4-2-u4-X04']::text[],false,'{"seq":1,"concept":"M4-2-u4-C3","difficulty":2,"kind":"mc","stem":"지도서 336 — 한 친구가 『수학』 88 ⑤의 다각형을 「5개: 가 / 6개: 다, 라 / 7개: 마, 사 / 8개: 나, 바」로 분류했어요. 잘못 넣은 다각형을 모두 고르세요.","options":[{"t":"라, 마, 바","correct":true},{"t":"가, 나","mis":"M4-2-u4-X04"},{"t":"라","mis":"M4-2-u4-X04"},{"t":"다, 사","mis":"M4-2-u4-X04"}],"explanation":["도형마다 변을 표시하며 다시 세요.","라는 변이 7개, 마는 8개, 바는 6개예요.","잘못 넣은 것은 라, 마, 바 — 변에 표시하며 세면 헷갈리지 않아요."],"asset":{"type":"geo","items":[{"w":96,"h":80,"poly":[[[87.39,34.45],[48.0,8.0],[8.61,34.45],[25.06,66.21],[70.94,66.21]]],"cap":"가"},{"w":96,"h":80,"poly":[[[88.0,40.0],[78.64,19.42],[44.51,8.13],[19.71,17.38],[8.0,40.0],[17.36,60.58],[48.0,72.0],[76.29,62.62]]],"cap":"나"},{"w":96,"h":80,"poly":[[[85.58,29.06],[54.94,8.48],[10.42,29.06],[10.42,50.94],[41.06,71.52],[82.64,56.0]]],"cap":"다"},{"w":96,"h":80,"poly":[[[88.0,40.0],[73.71,15.49],[41.06,8.48],[13.36,24.0],[10.42,50.94],[37.65,70.91],[70.94,66.21]]],"cap":"라"},{"w":96,"h":80,"poly":[[[86.64,31.71],[68.0,12.29],[41.06,8.48],[13.36,24.0],[8.61,45.55],[28.0,67.71],[54.94,71.52],[82.64,56.0]]],"cap":"마"},{"w":96,"h":80,"poly":[[[88.0,40.0],[61.68,9.94],[28.0,12.29],[8.0,40.0],[28.0,67.71],[68.0,67.71]]],"cap":"바"},{"w":96,"h":80,"poly":[[[84.26,26.48],[58.35,9.09],[22.29,15.49],[8.0,40.0],[17.36,60.58],[48.0,72.0],[78.64,60.58]]],"cap":"사"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u4_L03_challenge#2','math',4,2,'u4','L03','tb_g4_2_math_u4_L03_challenge','lesson_challenge','M4-2-u4-C2',2,'sa','auto','『수학』 89 ⑥ — 육각형, 칠각형, 팔각형을 하나씩 만들었어요. 세 다각형의 변은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"M4-2-u4-C2","difficulty":2,"kind":"sa","stem":"『수학』 89 ⑥ — 육각형, 칠각형, 팔각형을 하나씩 만들었어요. 세 다각형의 변은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["21"],"explanation":["육각형은 변 6개, 칠각형은 변 7개, 팔각형은 변 8개예요.","세 수를 더해요.","6 + 7 + 8 = 21개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u4_L03_challenge#3','math',4,2,'u4','L03','tb_g4_2_math_u4_L03_challenge','lesson_challenge','M4-2-u4-C3',3,'mc','auto','『수학익힘』 54 ② — 육각형을 찾아 고르세요.',ARRAY['M4-2-u4-X04','M4-2-u4-X01']::text[],false,'{"seq":3,"concept":"M4-2-u4-C3","difficulty":3,"kind":"mc","stem":"『수학익힘』 54 ② — 육각형을 찾아 고르세요.","options":[{"t":"가","correct":true},{"t":"다","mis":"M4-2-u4-X04"},{"t":"바","mis":"M4-2-u4-X04"},{"t":"라","mis":"M4-2-u4-X01"}],"explanation":["나, 라, 마는 다각형이 아니에요.","가는 변 6개, 다는 변 7개, 바는 변 8개예요.","육각형은 가예요."],"asset":{"type":"geo","items":[{"w":96,"h":80,"poly":[[[87.39,34.45],[48.0,8.0],[13.36,24.0],[10.42,50.94],[34.32,70.06],[78.64,60.58]]],"cap":"가"},{"w":96,"h":80,"seg":[[[9.6,16.0],[86.4,16.0]]],"curve":[[[9.6,16.0],[86.4,16.0],[48.0,96.0]]],"cap":"나"},{"w":96,"h":80,"poly":[[[63.27,71.71],[32.73,71.71],[13.68,47.83],[20.48,18.05],[48.0,4.8],[75.52,18.05],[82.32,47.83]]],"cap":"다"},{"w":96,"h":80,"seg":[[[8.0,73.6],[28.8,8.0]],[[28.8,8.0],[88.0,8.0]],[[88.0,8.0],[67.2,72.0]],[[67.2,72.0],[38.4,72.0]]],"cap":"라"},{"w":96,"h":80,"seg":[[[16.0,16.0],[16.0,64.0]],[[80.0,16.0],[80.0,64.0]]],"curve":[[[16.0,16.0],[80.0,16.0],[48.0,35.2]],[[16.0,64.0],[80.0,64.0],[48.0,86.4]]],"cap":"마"},{"w":96,"h":80,"poly":[[[61.47,72.52],[34.53,72.52],[15.48,53.47],[15.48,26.53],[34.53,7.48],[61.47,7.48],[80.52,26.53],[80.52,53.47]]],"cap":"바"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u4_L03_challenge#4','math',4,2,'u4','L03','tb_g4_2_math_u4_L03_challenge','lesson_challenge','M4-2-u4-C3',3,'mc','auto','지도서 335 이런 활동도 있어요 — 도형판에 오각형을 만든 뒤 꼭짓점을 하나만 옮겨 새 다각형을 만들었어요. 새 다각형의 이름은 무엇인가요?',ARRAY['M4-2-u4-X04','M4-2-u4-X05']::text[],false,'{"seq":4,"concept":"M4-2-u4-C3","difficulty":3,"kind":"mc","stem":"지도서 335 이런 활동도 있어요 — 도형판에 오각형을 만든 뒤 꼭짓점을 하나만 옮겨 새 다각형을 만들었어요. 새 다각형의 이름은 무엇인가요?","options":[{"t":"오각형","correct":true},{"t":"사각형","mis":"M4-2-u4-X04"},{"t":"육각형","mis":"M4-2-u4-X04"},{"t":"모양이 바뀌어 이름을 알 수 없다","mis":"M4-2-u4-X05"}],"explanation":["꼭짓점을 옮겨도 꼭짓점의 수는 그대로 5개예요.","꼭짓점이 5개이면 변도 5개예요.","모양은 달라졌지만 여전히 오각형이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u4_L03_challenge#5','math',4,2,'u4','L03','tb_g4_2_math_u4_L03_challenge','lesson_challenge','M4-2-u4-C3',3,'error','auto','『수학』 88 ⑥ — 육각형, 칠각형, 팔각형을 만들고 친구들과 비교했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M4-2-u4-X05','M4-2-u4-X20']::text[],false,'{"seq":5,"concept":"M4-2-u4-C3","difficulty":3,"kind":"error","stem":"『수학』 88 ⑥ — 육각형, 칠각형, 팔각형을 만들고 친구들과 비교했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민준 — 「내 육각형과 지아의 육각형은 모양이 다르니까 하나는 육각형이 아니야.」","correct":true,"mis_target":"M4-2-u4-X05"},{"t":"지아 — 「만든 방법은 달라도 육각형은 변이 모두 6개야.」","mis":"M4-2-u4-X20"},{"t":"서윤 — 「칠각형은 변이 7개, 꼭짓점도 7개야.」","mis":"M4-2-u4-X20"},{"t":"정후 — 「팔각형은 크기가 달라도 변이 8개야.」","mis":"M4-2-u4-X20"}],"explanation":["다각형의 이름은 변의 수로만 정해요.","모양이나 크기가 달라도 변이 6개이면 모두 육각형이에요.","민준이가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u4_L03_challenge#6','math',4,2,'u4','L03','tb_g4_2_math_u4_L03_challenge','lesson_challenge','M4-2-u4-C2',3,'sa','auto','『수학』 88 ⑤ — 가~사 일곱 다각형의 변은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"M4-2-u4-C2","difficulty":3,"kind":"sa","stem":"『수학』 88 ⑤ — 가~사 일곱 다각형의 변은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["47"],"explanation":["가 5개, 나 8개, 다 6개, 라 7개, 마 8개, 바 6개, 사 7개예요.","모두 더해요.","5 + 8 + 6 + 7 + 8 + 6 + 7 = 47개예요."],"asset":{"type":"geo","items":[{"w":96,"h":80,"poly":[[[87.39,34.45],[48.0,8.0],[8.61,34.45],[25.06,66.21],[70.94,66.21]]],"cap":"가"},{"w":96,"h":80,"poly":[[[88.0,40.0],[78.64,19.42],[44.51,8.13],[19.71,17.38],[8.0,40.0],[17.36,60.58],[48.0,72.0],[76.29,62.62]]],"cap":"나"},{"w":96,"h":80,"poly":[[[85.58,29.06],[54.94,8.48],[10.42,29.06],[10.42,50.94],[41.06,71.52],[82.64,56.0]]],"cap":"다"},{"w":96,"h":80,"poly":[[[88.0,40.0],[73.71,15.49],[41.06,8.48],[13.36,24.0],[10.42,50.94],[37.65,70.91],[70.94,66.21]]],"cap":"라"},{"w":96,"h":80,"poly":[[[86.64,31.71],[68.0,12.29],[41.06,8.48],[13.36,24.0],[8.61,45.55],[28.0,67.71],[54.94,71.52],[82.64,56.0]]],"cap":"마"},{"w":96,"h":80,"poly":[[[88.0,40.0],[61.68,9.94],[28.0,12.29],[8.0,40.0],[28.0,67.71],[68.0,67.71]]],"cap":"바"},{"w":96,"h":80,"poly":[[[84.26,26.48],[58.35,9.09],[22.29,15.49],[8.0,40.0],[17.36,60.58],[48.0,72.0],[78.64,60.58]]],"cap":"사"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u4_L03_challenge#7','math',4,2,'u4','L03','tb_g4_2_math_u4_L03_challenge','lesson_challenge','M4-2-u4-C3',3,'mc','auto','지도서 335 — 다각형(多角形)은 「각이 많은 평면도형」이라는 뜻이에요. 그렇다면 다각형의 이름(오각형, 육각형, …)은 무엇에 따라 정하나요?',ARRAY['M4-2-u4-X05','M4-2-u4-X07','M4-2-u4-X02']::text[],false,'{"seq":7,"concept":"M4-2-u4-C3","difficulty":3,"kind":"mc","stem":"지도서 335 — 다각형(多角形)은 「각이 많은 평면도형」이라는 뜻이에요. 그렇다면 다각형의 이름(오각형, 육각형, …)은 무엇에 따라 정하나요?","options":[{"t":"변의 수","correct":true},{"t":"크기","mis":"M4-2-u4-X05"},{"t":"각의 크기","mis":"M4-2-u4-X07"},{"t":"뾰족한 정도","mis":"M4-2-u4-X02"}],"explanation":["이름 앞의 수가 무엇을 세는지 생각해요.","변이 5개이면 오각형, 6개이면 육각형이에요.","다각형의 이름은 변의 수로 정해요(변의 수 = 꼭짓점의 수)."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u4_L03_challenge#8','math',4,2,'u4','L03','tb_g4_2_math_u4_L03_challenge','lesson_challenge','M4-2-u4-C3',4,'mc','auto','『수학』 88 ⑤ — 변의 수가 가장 많은 다각형을 모두 고르세요.',ARRAY['M4-2-u4-X04']::text[],false,'{"seq":8,"concept":"M4-2-u4-C3","difficulty":4,"kind":"mc","stem":"『수학』 88 ⑤ — 변의 수가 가장 많은 다각형을 모두 고르세요.","options":[{"t":"나, 마","correct":true},{"t":"라, 사","mis":"M4-2-u4-X04"},{"t":"나","mis":"M4-2-u4-X04"},{"t":"다, 바","mis":"M4-2-u4-X04"}],"explanation":["변을 세면 가 5, 나 8, 다 6, 라 7, 마 8, 바 6, 사 7개예요.","가장 많은 수는 8이에요.","변이 8개인 나, 마 — 팔각형 두 개예요."],"asset":{"type":"geo","items":[{"w":96,"h":80,"poly":[[[87.39,34.45],[48.0,8.0],[8.61,34.45],[25.06,66.21],[70.94,66.21]]],"cap":"가"},{"w":96,"h":80,"poly":[[[88.0,40.0],[78.64,19.42],[44.51,8.13],[19.71,17.38],[8.0,40.0],[17.36,60.58],[48.0,72.0],[76.29,62.62]]],"cap":"나"},{"w":96,"h":80,"poly":[[[85.58,29.06],[54.94,8.48],[10.42,29.06],[10.42,50.94],[41.06,71.52],[82.64,56.0]]],"cap":"다"},{"w":96,"h":80,"poly":[[[88.0,40.0],[73.71,15.49],[41.06,8.48],[13.36,24.0],[10.42,50.94],[37.65,70.91],[70.94,66.21]]],"cap":"라"},{"w":96,"h":80,"poly":[[[86.64,31.71],[68.0,12.29],[41.06,8.48],[13.36,24.0],[8.61,45.55],[28.0,67.71],[54.94,71.52],[82.64,56.0]]],"cap":"마"},{"w":96,"h":80,"poly":[[[88.0,40.0],[61.68,9.94],[28.0,12.29],[8.0,40.0],[28.0,67.71],[68.0,67.71]]],"cap":"바"},{"w":96,"h":80,"poly":[[[84.26,26.48],[58.35,9.09],[22.29,15.49],[8.0,40.0],[17.36,60.58],[48.0,72.0],[78.64,60.58]]],"cap":"사"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u4_L03_challenge#9','math',4,2,'u4','L03','tb_g4_2_math_u4_L03_challenge','lesson_challenge','M4-2-u4-C2',4,'sa','auto','『수학』 89 ⑥ — 도형판에 고무줄로 팔각형을 만들려고 해요. 고무줄을 걸어 꼭짓점이 될 못은 몇 개 있어야 하나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"M4-2-u4-C2","difficulty":4,"kind":"sa","stem":"『수학』 89 ⑥ — 도형판에 고무줄로 팔각형을 만들려고 해요. 고무줄을 걸어 꼭짓점이 될 못은 몇 개 있어야 하나요? 숫자로 쓰세요.","answer":["8"],"explanation":["고무줄을 건 못 하나하나가 꼭짓점이 돼요.","팔각형은 변이 8개이므로 꼭짓점도 8개예요.","못은 8개 있어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u4_L03_challenge#10','math',4,2,'u4','L03','tb_g4_2_math_u4_L03_challenge','lesson_challenge','M4-2-u4-C3',4,'essay','teacher','『수학』 88 ⑤ — 다각형을 변의 수에 따라 분류하고 이름을 붙이는 방법을 설명하고, 표를 보고 알게 된 점을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M4-2-u4-C3","difficulty":4,"kind":"essay","stem":"『수학』 88 ⑤ — 다각형을 변의 수에 따라 분류하고 이름을 붙이는 방법을 설명하고, 표를 보고 알게 된 점을 써 보세요.","answer_guide":{"answer":"예: 다각형은 변의 수에 따라 변이 5개이면 오각형, 6개이면 육각형, 7개이면 칠각형, 8개이면 팔각형이라고 한다. 다각형의 이름이 같으면 변의 수와 꼭짓점의 수가 같다.","scoring_points":["변의 수로 이름을 붙인다고 썼는가","오각형~팔각형을 바르게 썼는가","변의 수와 꼭짓점의 수가 같다고 썼는가"]},"explanation":["변에 표시하며 세어 분류해요.","변 5·6·7·8개 → 오각형·육각형·칠각형·팔각형.","이름이 같으면 변의 수와 꼭짓점의 수가 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u4_L04_basic#1','math',4,2,'u4','L04','tb_g4_2_math_u4_L04_basic','lesson_basic','M4-2-u4-C4',1,'blank','auto','변의 길이가 모두 같고 각의 크기가 모두 같은 다각형을 □(이)라고 합니다. □에 알맞은 말은 무엇인가요?',ARRAY['M4-2-u4-X07','M4-2-u4-X11','M4-2-u4-X10']::text[],false,'{"seq":1,"concept":"M4-2-u4-C4","difficulty":1,"kind":"blank","stem":"변의 길이가 모두 같고 각의 크기가 모두 같은 다각형을 □(이)라고 합니다. □에 알맞은 말은 무엇인가요?","options":[{"t":"정다각형","correct":true},{"t":"다각형","mis":"M4-2-u4-X07"},{"t":"대각선","mis":"M4-2-u4-X11"},{"t":"정사각형","mis":"M4-2-u4-X10"}],"explanation":["그릇에서 찾은 다각형을 변의 길이와 각의 크기로 분류해 봤어요.","두 가지가 모두 같은 다각형이 정다각형이에요.","정삼각형, 정사각형, 정오각형, 정육각형… 모두 정다각형이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u4_L04_basic#2','math',4,2,'u4','L04','tb_g4_2_math_u4_L04_basic','lesson_basic','M4-2-u4-C4',1,'mc','auto','『수학』 91 — 변의 길이가 모두 같고 각의 크기가 모두 같은 이 다각형의 이름은 무엇인가요?',ARRAY['M4-2-u4-X07','M4-2-u4-X04']::text[],true,'{"seq":2,"concept":"M4-2-u4-C4","difficulty":1,"kind":"mc","stem":"『수학』 91 — 변의 길이가 모두 같고 각의 크기가 모두 같은 이 다각형의 이름은 무엇인가요?","options":[{"t":"정오각형","correct":true},{"t":"오각형","mis":"M4-2-u4-X07"},{"t":"정육각형","mis":"M4-2-u4-X04"},{"t":"정사각형","mis":"M4-2-u4-X04"}],"explanation":["변이 5개예요.","변의 길이와 각의 크기가 모두 같아요.","변이 5개인 정다각형이니 정오각형이에요."],"asset":{"type":"geo","items":[{"w":121.7,"h":115.2,"poly":[[[81.038121605,91.214781741],[26.961878395,91.214781741],[10.25140025,39.785218259],[54.0,8.0],[97.74859975,39.785218259]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 『수학』 91 — 변의 길이가 모두 같고 각의 크기가 모두 같은 이 다각형의 이름은 무엇인가요?","options":[{"t":"정육각형","correct":true},{"t":"육각형","mis":"M4-2-u4-X07"},{"t":"정오각형","mis":"M4-2-u4-X04"},{"t":"정팔각형","mis":"M4-2-u4-X04"}],"explanation":["변이 6개예요.","변의 길이와 각의 크기가 모두 같아요.","변이 6개인 정다각형이니 정육각형이에요."],"asset":{"type":"geo","items":[{"w":124.0,"h":117.8,"poly":[[[77.0,93.837168574],[31.0,93.837168574],[8.0,54.0],[31.0,14.162831426],[77.0,14.162831426],[100.0,54.0]]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 『수학』 91 — 변의 길이가 모두 같고 각의 크기가 모두 같은 이 다각형의 이름은 무엇인가요?","options":[{"t":"정삼각형","correct":true},{"t":"이등변삼각형","mis":"M4-2-u4-X21"},{"t":"정사각형","mis":"M4-2-u4-X04"},{"t":"삼각형","mis":"M4-2-u4-X07"}],"explanation":["변이 3개예요.","세 변의 길이와 세 각의 크기가 모두 같아요.","정삼각형이에요."],"asset":{"type":"geo","items":[{"w":117.8,"h":101.0,"poly":[[[93.837168574,77.0],[14.162831426,77.0],[54.0,8.0]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qk